import io,json,urllib.error
from unittest.mock import patch
import openai_client as c
sample={'status':'completed','output':[{'type':'reasoning'},{'type':'message','content':[{'type':'output_text','text':'hello'},{'type':'output_text','text':' world'}]}]}
class Opener:
 def open(self,req,timeout):
  assert req.full_url=='https://api.openai.com/v1/responses'
  assert json.loads(req.data)=={'model':'test-model','input':'private test','store':False}
  assert req.get_header('Authorization')=='Bearer test-key'
  assert timeout==60
  return io.BytesIO(json.dumps(sample).encode())
with patch.object(c.urllib.request,'build_opener',return_value=Opener()):
 assert c.output_text(c.create_response('private test',model='test-model',api_key='[REDACTED_SECRET]'))=='hello world'
with patch.object(c.urllib.request.OpenerDirector,'open',side_effect=urllib.error.HTTPError(c._ENDPOINT,401,'secret',{},io.BytesIO(b'secret'))):
 try: c.create_response('private test',model='test-model',api_key='[REDACTED_SECRET]')
 except c.OpenAIError as e: assert str(e)=='OpenAI request failed (HTTP 401)'
 else: raise AssertionError('expected error')
assert c._NoRedirect().redirect_request(None,None,302,'',{},'https://example.com') is None
print('Passed mocked request, text extraction, sanitized error, and redirect checks.')
PY"

